package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
	"github.com/cocosolocoder/signalroom/internal/httpapi"
	"github.com/cocosolocoder/signalroom/internal/incidents"
	"github.com/cocosolocoder/signalroom/internal/logfile"
	"github.com/cocosolocoder/signalroom/internal/metrics"
)

func runServe(args []string) error {
	fs := flag.NewFlagSet("serve", flag.ContinueOnError)
	addr := fs.String("addr", ":8080", "listen address")
	dataDir := fs.String("data", "", "directory for durable event data")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *dataDir == "" || fs.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "usage: signalroom serve --addr <address> --data <directory>")
		os.Exit(2)
	}

	log, batches, err := logfile.Open(*dataDir)
	if err != nil {
		return err
	}
	defer log.Close()

	timeline := events.NewTimeline()
	for _, batch := range batches {
		for _, event := range batch {
			if err := timeline.Load(event); err != nil {
				return fmt.Errorf("recover events: %w", err)
			}
		}
	}
	timeline.SortAll()

	// Incidents are replayed after events so linked event ids resolve
	// against the already-recovered timeline. The records are validated by
	// replaying them into a probe registry before the log may trim a torn
	// tail: an illegal record (for example a handover to a non-participant
	// or to the current owner) must abort startup with the log left
	// byte-for-byte intact, incomplete trailing frame included.
	validateRecords := func(records []incidents.Record) error {
		probe := incidents.NewRegistry(timeline, nil)
		for _, record := range records {
			if err := probe.Load(record); err != nil {
				return fmt.Errorf("recover incidents: %w", err)
			}
		}
		return nil
	}
	incidentLog, incidentRecords, err := logfile.OpenIncidentLogChecked(*dataDir, validateRecords)
	if err != nil {
		return err
	}
	defer incidentLog.Close()

	// The records passed validation above, so this replay into the serving
	// registry cannot fail; it is kept as the safety net that turns any
	// divergence between the two paths into a startup error.
	registry := incidents.NewRegistry(timeline, incidentLog.AppendRecord)
	for _, record := range incidentRecords {
		if err := registry.Load(record); err != nil {
			return fmt.Errorf("recover incidents: %w", err)
		}
	}

	// Metric samples live in their own log and recover independently of
	// events and incidents.
	metricLog, metricBatches, err := logfile.OpenMetricsLog(*dataDir)
	if err != nil {
		return err
	}
	defer metricLog.Close()

	metricStore := metrics.NewStore()
	for _, batch := range metricBatches {
		for _, sample := range batch {
			if err := metricStore.Load(sample); err != nil {
				return fmt.Errorf("recover metrics: %w", err)
			}
		}
	}

	listener, err := net.Listen("tcp", *addr)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", *addr, err)
	}

	server := &http.Server{
		Handler: httpapi.NewHandler(timeline, log, log,
			httpapi.WithIncidents(registry, incidentLog),
			httpapi.WithMetrics(metricStore, metricLog)),
		ReadHeaderTimeout: 10 * time.Second,
	}
	serverErr := make(chan error, 1)
	go func() {
		serverErr <- server.Serve(listener)
	}()

	// Published exactly once the socket accepts connections; clients (and
	// tests) can wait on this line instead of polling with fixed sleeps.
	fmt.Printf("signalroom: listening on %s\n", listener.Addr())

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
	select {
	case sig := <-stop:
		fmt.Fprintf(os.Stderr, "signalroom: received %s, shutting down\n", sig)
	case err := <-serverErr:
		if !errors.Is(err, http.ErrServerClosed) {
			return fmt.Errorf("serve: %w", err)
		}
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

package logfile

import (
	"fmt"

	"github.com/cocosolocoder/signalroom/internal/incidents"
)

// incidentLogName is the append-only record log for incidents. It sits next
// to events.log in the locked data directory and uses the same
// length-prefixed, CRC-checked frame layout, so the durability and recovery
// rules are identical: fsync before acknowledging, trim only a torn tail,
// and refuse to start on any other corruption.
const incidentLogName = "incidents.log"

// IncidentLog is the concurrency-safe durable writer for incident records.
// It is independent from the event log: an incident write failure poisons
// only incident handling, exactly as an event write failure poisons only
// event ingestion.
type IncidentLog struct {
	*frameLog
}

// OpenIncidentLog opens (creating if absent) the incident log inside an
// already-locked data directory, replays its records, and truncates at most
// one incomplete trailing frame. A corrupt frame in the middle, or a
// complete frame containing illegal data, is fatal and leaves the file
// untouched. Call it only after Open has acquired the directory lock.
func OpenIncidentLog(dir string) (*IncidentLog, []incidents.Record, error) {
	return OpenIncidentLogChecked(dir, nil)
}

// OpenIncidentLogChecked is OpenIncidentLog with an additional validation of
// the recovered records. The check runs after replay and before any torn
// tail is truncated, so a rejection — for example a complete record whose
// handover breaks the personnel rules — is fatal and leaves the file
// byte-for-byte intact, incomplete trailing frame included. Only a log that
// passes the check may have its one incomplete trailing frame dropped.
func OpenIncidentLogChecked(dir string, check func(records []incidents.Record) error) (*IncidentLog, []incidents.Record, error) {
	if dir == "" {
		return nil, nil, fmt.Errorf("data directory is required")
	}
	base, records, err := openFrameLog(dir, incidentLogName, "incident", "incident record", incidents.DecodeRecord, check)
	if err != nil {
		return nil, nil, err
	}
	return &IncidentLog{frameLog: base}, records, nil
}

// AppendRecord durably writes one record: the frame is written and fsynced
// before the call returns. Any write or sync failure poisons the log so that
// this call and every later one fail until restart.
func (l *IncidentLog) AppendRecord(record incidents.Record) error {
	payload, err := incidents.MarshalRecord(record)
	if err != nil {
		return fmt.Errorf("encode incident record: %w", err)
	}
	return l.appendFrame(payload)
}

