1	package logfile
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"sync"
11	)
12	
13	const (
14		headerSize = 8
15		// MaxPayloadBytes is the 64 MiB (1024*1024-byte units) capacity of one
16		// frame payload. It bounds the saved content itself, excluding the
17		// 8-byte frame header, and guards against absurd allocations when a
18		// corrupt length prefix happens to point inside the file.
19		MaxPayloadBytes = 64 << 20
20	)
21	
22	// ErrPayloadTooLarge is returned when a frame's encoded content exceeds
23	// MaxPayloadBytes. It describes the content, not a storage fault: the check
24	// runs before anything is written or locked for mutation, the log is not
25	// poisoned, and later writes keep working without a restart.
26	var ErrPayloadTooLarge = errors.New("frame payload exceeds the 64 MiB save capacity")
27	
28	// ErrPoisoned is returned after a write or sync failure. The log refuses all
29	// further writes until the process is restarted and recovery succeeds.
30	var ErrPoisoned = errors.New("log is unavailable after a storage failure")
31	
32	// CorruptionError marks a complete frame that fails its checksum or contains
33	// illegal data, as opposed to an incomplete trailing frame.
34	type CorruptionError struct{ Reason string }
35	
36	func (e *CorruptionError) Error() string { return e.Reason }
37	
38	func corruption(format string, args ...any) error {
39		return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
40	}
41	
42	// frameLog is the shared append-only frame writer behind the event, incident,
43	// and metric logs. It owns the frame layout, torn-tail recovery, and the
44	// poison-on-failure write path; each concrete log supplies only its own
45	// payload encoding and content validation, so the durability rule lives in
46	// exactly one place.
47	type frameLog struct {
48		mu       sync.Mutex
49		file     *os.File
50		dir      string
51		noun     string // the log's name in error messages: "event", "incident", "metrics"
52		unit     string // what one frame holds: "batch", "incident record", "metric batch"
53		poisoned bool
54	}
55	
56	// openFrameLog opens (creating if absent) the named log inside an
57	// already-locked data directory, replays its frames with decode, and
58	// truncates at most one incomplete trailing frame. A corrupt frame in the
59	// middle, or a complete frame whose payload decode rejects, is fatal and
60	// leaves the file untouched. When check is non-nil it validates the
61	// recovered items after replay and before any truncation, so a rejection
62	// there is also fatal without modifying a single byte of the file.
63	func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error), check func(items []T) error) (*frameLog, []T, error) {
64		path := filepath.Join(dir, name)
65		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
66		if err != nil {
67			return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
68		}
69	
70		items, validLen, err := replayFrames(file, noun, decode)
71		if err != nil {
72			file.Close()
73			return nil, nil, err
74		}
75		if check != nil {
76			if err := check(items); err != nil {
77				file.Close()
78				return nil, nil, err
79			}
80		}
81		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
82			// Drop exactly one incomplete trailing frame; the only mutation
83			// recovery performs, fsynced before serving.
84			if err := file.Truncate(validLen); err != nil {
85				file.Close()
86				return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
87			}
88			if err := file.Sync(); err != nil {
89				file.Close()
90				return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
91			}
92		}
93		// Flush the directory so the log file's own entry is durable, whether it
94		// was just created or just truncated.
95		if err := syncDir(dir); err != nil {
96			file.Close()
97			return nil, nil, fmt.Errorf("sync data directory: %w", err)
98		}
99	
100		return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
101	}
102	
103	// replayFrames scans the log and returns the decoded frames and the byte
104	// offset at which the log is known good. A torn trailing frame — a partial
105	// header, or a header whose payload never fully landed — ends the scan
106	// without error; any corruption before that offset is fatal.
107	func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
108		data, err := os.ReadFile(file.Name())
109		if err != nil {
110			return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
111		}
112	
113		var items []T
114		pos := int64(0)
115		for pos < int64(len(data)) {
116			remaining := int64(len(data)) - pos
117			if remaining < headerSize {
118				break // torn partial header
119			}
120			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
121			if payloadLen <= 0 || payloadLen > MaxPayloadBytes {
122				return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
123			}
124			frameEnd := pos + headerSize + payloadLen
125			if frameEnd > int64(len(data)) {
126				break // header landed but its payload did not: torn tail
127			}
128			payload := data[pos+headerSize : frameEnd]
129			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
130			if crc32.ChecksumIEEE(payload) != wantCRC {
131				return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
132			}
133			item, err := decode(payload)
134			if err != nil {
135				return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
136			}
137			items = append(items, item)
138			pos = frameEnd
139		}
140		return items, pos, nil
141	}
142	
143	// appendFrame durably writes one already-encoded payload: the frame is
144	// written and fsynced before the call returns. Any write or sync failure
145	// poisons the log, so this call and every later one fail until restart. A
146	// payload that fails the size check returns ErrPayloadTooLarge before the
147	// log is touched and does not poison it.
148	func (l *frameLog) appendFrame(payload []byte) (err error) {
149		if len(payload) > MaxPayloadBytes {
150			return fmt.Errorf("%w: %s is %d bytes", ErrPayloadTooLarge, l.unit, len(payload))
151		}
152	
153		frame := make([]byte, headerSize+len(payload))
154		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
155		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
156		copy(frame[headerSize:], payload)
157	
158		l.mu.Lock()
159		defer l.mu.Unlock()
160		if l.poisoned {
161			return ErrPoisoned
162		}
163		defer func() {
164			if err != nil {
165				l.poisoned = true
166			}
167		}()
168	
