1	package events
2	
3	import (
4		"errors"
5		"fmt"
6		"maps"
7		"sort"
8		"sync"
9		"time"
10	)
11	
12	// MaxBatchPayloadBytes bounds what one save may hold in the on-disk save
13	// format (MarshalBatch): 64 MiB in 1024*1024-byte units, matching the durable
14	// frame capacity. It measures the encoded JSON content of the newly saved
15	// events only — not any replayed events and not the surrounding frame
16	// header. A batch encoding to exactly this size is still accepted; only a
17	// larger encoding is rejected.
18	const MaxBatchPayloadBytes = 64 << 20
19	
20	// BeforeCommit persists a batch of brand-new events. It runs while the
21	// timeline lock is held and before the batch becomes visible to queries, so a
22	// successful return guarantees the batch is durable and committed atomically.
23	// Returning an error rejects the batch without touching the timeline.
24	type BeforeCommit func(persisted []Event) error
25	
26	// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
27	// whole batches and reports replays of already-stored events.
28	type Timeline struct {
29		mu     sync.RWMutex
30		byID   map[string]Event
31		events []Event
32	}
33	
34	// NewTimeline returns an empty timeline.
35	func NewTimeline() *Timeline {
36		return &Timeline{byID: make(map[string]Event)}
37	}
38	
39	// IngestResult counts how a batch was applied: Created events are new,
40	// Replayed events matched an existing event with the same id and content.
41	type IngestResult struct {
42		Created  int
43		Replayed int
44	}
45	
46	// OversizeBatchError reports that the brand-new events of a batch encode to
47	// more than MaxBatchPayloadBytes in the save format. It is a property of the
48	// request content, not of the storage: nothing is written, the store stays
49	// usable without a restart, the rejected ids remain free, and the same
50	// events are accepted once submitted in smaller batches. Replayed events are
51	// not part of the measured payload.
52	type OversizeBatchError struct {
53		Size  int
54		Limit int
55	}
56	
57	func (e *OversizeBatchError) Error() string {
58		return fmt.Sprintf("event batch saves to %d bytes, exceeding the %d byte save capacity; reduce the amount of content in a single submission", e.Size, e.Limit)
59	}
60	
61	// IsOversizeBatchError reports whether err is a batch that exceeds the save
62	// capacity, as opposed to a validation, conflict, or storage failure.
63	func IsOversizeBatchError(err error) bool {
64		var target *OversizeBatchError
65		return errors.As(err, &target)
66	}
67	
68	// Ingest normalizes and validates every event first, then checks the whole
69	// batch against existing events and itself. Validation failures produce a
70	// ValidationError; duplicate ids with differing content, or a repeated id
71	// within the batch, produce a ConflictError. Nothing is stored when an error
72	// is returned.
73	//
74	// New events are passed to beforeCommit for durable storage; only after it
75	// succeeds does the batch become visible, so concurrent readers see either
76	// the complete batch or none of it.
77	func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
78		normalized := make([]Event, len(batch))
79		for i, event := range batch {
80			norm, err := Normalize(event)
81			if err != nil {
82				return IngestResult{}, err
83			}
84			normalized[i] = norm
85		}
86	
87		t.mu.Lock()
88		defer t.mu.Unlock()
89	
90		pending := make(map[string]struct{}, len(normalized))
91		var created []Event
92		var result IngestResult
93		for _, event := range normalized {
94			if _, repeated := pending[event.ID]; repeated {
95				return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
96			}
97			pending[event.ID] = struct{}{}
98			if existing, ok := t.byID[event.ID]; ok {
99				if !sameEvent(existing, event) {
100					return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
101				}
102				result.Replayed++
103				continue
104			}
105			created = append(created, event)
106			result.Created++
107		}
108	
109		// Only brand-new events are saved, so only they count toward the save
110		// capacity: a batch made entirely (or partly) of identical retries is
111		// measured by what would actually be written. The check runs after
112		// validation and conflict checks but before beforeCommit, so an oversize
113		// batch neither touches durable storage nor marks the store unavailable.
114		if len(created) > 0 {
115			payload, err := MarshalBatch(created)
116			if err != nil {
117				return IngestResult{}, err
118			}
119			if len(payload) > MaxBatchPayloadBytes {
120				return IngestResult{}, &OversizeBatchError{Size: len(payload), Limit: MaxBatchPayloadBytes}
121			}
122			if beforeCommit != nil {
123				if err := beforeCommit(created); err != nil {
124					return IngestResult{}, err
125				}
126			}
127			for _, event := range created {
128				t.byID[event.ID] = event
129				t.events = append(t.events, event)
130			}
131			sort.SliceStable(t.events, func(i, j int) bool {
132				return byTimeThenID(t.events[i], t.events[j])
133			})
134		}
135		return result, nil
136	}
