203	// time-then-id order. The set is taken under the timeline lock, so a batch
204	// committed concurrently is either fully present or fully absent; events
205	// added after the call never appear in the returned set, which makes it
206	// suitable for stable pagination across later writes.
207	func (t *Timeline) SnapshotIDs(query Query) []string {
208		filter := NewFilter(query.Service, query.Severity, query.Labels)
209	
210		t.mu.RLock()
211		defer t.mu.RUnlock()
