package events

import (
	"errors"
	"fmt"
	"maps"
	"sort"
	"sync"
	"time"
)

// MaxBatchPayloadBytes bounds what one save may hold in the on-disk save
// format (MarshalBatch): 64 MiB in 1024*1024-byte units, matching the durable
// frame capacity. It measures the encoded JSON content of the newly saved
// events only — not any replayed events and not the surrounding frame
// header. A batch encoding to exactly this size is still accepted; only a
// larger encoding is rejected.
const MaxBatchPayloadBytes = 64 << 20

// BeforeCommit persists a batch of brand-new events. It runs while the
// timeline lock is held and before the batch becomes visible to queries, so a
// successful return guarantees the batch is durable and committed atomically.
// Returning an error rejects the batch without touching the timeline.
type BeforeCommit func(persisted []Event) error

// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
// whole batches and reports replays of already-stored events.
type Timeline struct {
	mu     sync.RWMutex
	byID   map[string]Event
	events []Event
}

// NewTimeline returns an empty timeline.
func NewTimeline() *Timeline {
	return &Timeline{byID: make(map[string]Event)}
}

// IngestResult counts how a batch was applied: Created events are new,
// Replayed events matched an existing event with the same id and content.
type IngestResult struct {
	Created  int
	Replayed int
}

// OversizeBatchError reports that the brand-new events of a batch encode to
// more than MaxBatchPayloadBytes in the save format. It is a property of the
// request content, not of the storage: nothing is written, the store stays
// usable without a restart, the rejected ids remain free, and the same
// events are accepted once submitted in smaller batches. Replayed events are
// not part of the measured payload.
type OversizeBatchError struct {
	Size  int
	Limit int
}

func (e *OversizeBatchError) Error() string {
	return fmt.Sprintf("event batch saves to %d bytes, exceeding the %d byte save capacity; reduce the amount of content in a single submission", e.Size, e.Limit)
}

// IsOversizeBatchError reports whether err is a batch that exceeds the save
// capacity, as opposed to a validation, conflict, or storage failure.
func IsOversizeBatchError(err error) bool {
	var target *OversizeBatchError
	return errors.As(err, &target)
}

// Ingest normalizes and validates every event first, then checks the whole
// batch against existing events and itself. Validation failures produce a
// ValidationError; duplicate ids with differing content, or a repeated id
// within the batch, produce a ConflictError. Nothing is stored when an error
// is returned.
//
// New events are passed to beforeCommit for durable storage; only after it
// succeeds does the batch become visible, so concurrent readers see either
// the complete batch or none of it.
func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
	normalized := make([]Event, len(batch))
	for i, event := range batch {
		norm, err := Normalize(event)
		if err != nil {
			return IngestResult{}, err
		}
		normalized[i] = norm
	}

	t.mu.Lock()
	defer t.mu.Unlock()

	pending := make(map[string]struct{}, len(normalized))
	var created []Event
	var result IngestResult
	for _, event := range normalized {
		if _, repeated := pending[event.ID]; repeated {
			return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
		}
		pending[event.ID] = struct{}{}
		if existing, ok := t.byID[event.ID]; ok {
			if !sameEvent(existing, event) {
				return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
			}
			result.Replayed++
			continue
		}
		created = append(created, event)
		result.Created++
	}

	// Only brand-new events are saved, so only they count toward the save
	// capacity: a batch made entirely (or partly) of identical retries is
	// measured by what would actually be written. The check runs after
	// validation and conflict checks but before beforeCommit, so an oversize
	// batch neither touches durable storage nor marks the store unavailable.
	if len(created) > 0 {
		payload, err := MarshalBatch(created)
		if err != nil {
			return IngestResult{}, err
		}
		if len(payload) > MaxBatchPayloadBytes {
			return IngestResult{}, &OversizeBatchError{Size: len(payload), Limit: MaxBatchPayloadBytes}
		}
		if beforeCommit != nil {
			if err := beforeCommit(created); err != nil {
				return IngestResult{}, err
			}
		}
		for _, event := range created {
			t.byID[event.ID] = event
			t.events = append(t.events, event)
		}
		sort.SliceStable(t.events, func(i, j int) bool {
			return byTimeThenID(t.events[i], t.events[j])
		})
	}
	return result, nil
}

// Load inserts events recovered from durable storage during startup. Every
// event must already be normalized; a duplicate id with differing content is
// reported as a conflict naming the id, so the caller can fail rather than
// mutate data.
func (t *Timeline) Load(event Event) error {
	if _, err := Normalize(event); err != nil {
		return err
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if existing, ok := t.byID[event.ID]; ok {
		if !sameEvent(existing, event) {
			return &ConflictError{Reason: fmt.Sprintf("event id %q already exists with different content", event.ID)}
		}
		return nil
	}
	t.byID[event.ID] = event
	t.events = append(t.events, event)
	return nil
}

// SortAll orders recovered events by time, then id. Call it once after Load.
func (t *Timeline) SortAll() {
	t.mu.Lock()
	defer t.mu.Unlock()
	sort.SliceStable(t.events, func(i, j int) bool {
		return byTimeThenID(t.events[i], t.events[j])
	})
}

// withinBounds reports whether at falls in the inclusive [Since, Until]
// range. A nil bound means unbounded in that direction, so an explicit
// boundary at the zero instant is still applied. Comparisons use absolute
// instants, so time zone spellings of the same moment agree.
func (q Query) withinBounds(at time.Time) bool {
	if q.Since != nil && at.Before(*q.Since) {
		return false
	}
	if q.Until != nil && at.After(*q.Until) {
		return false
	}
	return true
}

// Query returns the events matching the optional filters, ordered by time and
// then by id. Time equality uses absolute instants.
func (t *Timeline) Query(query Query) []Event {
	filter := NewFilter(query.Service, query.Severity, query.Labels)

	t.mu.RLock()
	defer t.mu.RUnlock()
	result := make([]Event, 0, len(t.events))
	for _, event := range t.events {
		if !filter.Matches(event) {
			continue
		}
		if !query.withinBounds(event.At) {
			continue
		}
		result = append(result, event)
	}
	return result
}

// SnapshotIDs returns the ids of events matching the optional filters, in
// time-then-id order. The set is taken under the timeline lock, so a batch
// committed concurrently is either fully present or fully absent; events
// added after the call never appear in the returned set, which makes it
// suitable for stable pagination across later writes.
func (t *Timeline) SnapshotIDs(query Query) []string {
	filter := NewFilter(query.Service, query.Severity, query.Labels)

	t.mu.RLock()
	defer t.mu.RUnlock()
	ids := make([]string, 0, len(t.events))
	for _, event := range t.events {
		if !filter.Matches(event) {
			continue
		}
		if !query.withinBounds(event.At) {
			continue
		}
		ids = append(ids, event.ID)
	}
	return ids
}

// LookupEvent returns the service of a stored event, or ok=false when the id
// is unknown. It never mutates the timeline, which lets incident handling
// link events without changing them.
func (t *Timeline) LookupEvent(id string) (service string, ok bool) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	event, found := t.byID[id]
	if !found {
		return "", false
	}
	return event.Service, true
}

// EventsByID returns the events for ids in the requested order. Every id
// must refer to a stored event; events are never removed, so a set captured
// by SnapshotIDs stays resolvable. Missing ids are skipped only when the
// caller passes ids not produced by SnapshotIDs.
func (t *Timeline) EventsByID(ids []string) []Event {
	t.mu.RLock()
	defer t.mu.RUnlock()
	out := make([]Event, 0, len(ids))
	for _, id := range ids {
		if event, ok := t.byID[id]; ok {
			out = append(out, event)
		}
	}
	return out
}

// sameEvent compares two normalized events on their absolute instant and
// their labels. Normalized label sets are nil when empty, so the three "no
// labels" spellings compare equal, and map comparison makes key order and
// original whitespace irrelevant.
func sameEvent(a, b Event) bool {
	return a.ID == b.ID &&
		a.Service == b.Service &&
		a.Severity == b.Severity &&
		a.Message == b.Message &&
		a.At.Equal(b.At) &&
		maps.Equal(a.Labels, b.Labels)
}

