1	package httpapi
2	
3	import (
4		"bytes"
5		"errors"
6		"net/http"
7		"strconv"
8		"strings"
9		"time"
10	
11		"github.com/cocosolocoder/signalroom/internal/events"
12		"github.com/cocosolocoder/signalroom/internal/metrics"
13	)
14	
15	// MetricStorage durably persists a metric batch before it becomes visible and
16	// reports whether metric storage has failed.
17	type MetricStorage interface {
18		Append(batch []metrics.Sample) error
19		Poisoned() bool
20	}
21	
22	// allowedMetricsFields is the exact set of members a POST /metrics body may
23	// carry.
24	var allowedMetricsFields = map[string]struct{}{
25		"samples": {},
26	}
27	
28	type ingestMetricsResponse struct {
29		Created  int `json:"created"`
30		Replayed int `json:"replayed"`
31	}
32	
33	type aggregateSeriesDTO struct {
34		Service  string                `json:"service"`
35		Labels   map[string]string     `json:"labels,omitempty"`
36		Segments []aggregateSegmentDTO `json:"segments"`
37	}
38	
39	type aggregateSegmentDTO struct {
40		Since string  `json:"since"`
41		Until string  `json:"until"`
42		Count int     `json:"count"`
43		Delta float64 `json:"delta"`
44	}
45	
46	func (h *Handler) metricsRoot(w http.ResponseWriter, r *http.Request) {
47		if r.Method != http.MethodPost {
48			w.Header().Set("Allow", "POST")
49			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
50			return
51		}
52		h.postMetrics(w, r)
53	}
54	
55	func (h *Handler) metricsAggregate(w http.ResponseWriter, r *http.Request) {
56		if r.Method != http.MethodGet {
57			w.Header().Set("Allow", "GET")
58			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
59			return
60		}
61		h.getMetricsAggregate(w, r)
62	}
63	
64	func (h *Handler) metricsUnavailable(w http.ResponseWriter) bool {
65		if h.metricLogs == nil || h.metricLogs.Poisoned() {
66			writeError(w, http.StatusServiceUnavailable, "metric storage is unavailable; restart required")
67			return true
68		}
69		return false
70	}
71	
72	func (h *Handler) postMetrics(w http.ResponseWriter, r *http.Request) {
73		if h.metricsUnavailable(w) {
74			return
75		}
76	
77		body, err := readJSONObjectBody(w, r, allowedMetricsFields)
78		if err != nil {
79			writeError(w, http.StatusBadRequest, "invalid JSON body")
80			return
81		}
82		rawSamples, present := body["samples"]
83		trimmed := bytes.TrimSpace(rawSamples)
84		if !present || bytes.Equal(trimmed, []byte("null")) || bytes.Equal(trimmed, []byte("[]")) {
85			writeError(w, http.StatusBadRequest, "samples must be a non-empty array")
86			return
87		}
88	
89		batch, err := metrics.DecodeBatch(rawSamples)
90		if err != nil {
91			writeError(w, http.StatusBadRequest, "invalid samples array")
92			return
93		}
94		if len(batch) == 0 {
95			writeError(w, http.StatusBadRequest, "samples must not be empty")
96			return
97		}
98	
99		result, err := h.metrics.Ingest(batch, h.metricLogs.Append)
100		if err != nil {
101			switch {
102			case metrics.IsValidationError(err):
103				writeError(w, http.StatusBadRequest, err.Error())
104			case metrics.IsOversizeBatchError(err):
105				writeError(w, http.StatusBadRequest, err.Error())
106			case metrics.IsConflictError(err):
107				writeError(w, http.StatusConflict, err.Error())
108			default:
109				writeError(w, http.StatusServiceUnavailable, "metric storage is unavailable; restart required")
110			}
111			return
112		}
113	
114		writeJSON(w, http.StatusOK, ingestMetricsResponse{
115			Created: result.Created, Replayed: result.Replayed,
116		})
117	}
118	
119	func (h *Handler) getMetricsAggregate(w http.ResponseWriter, r *http.Request) {
120		if h.metricsUnavailable(w) {
121			return
122		}
123	
124		values := r.URL.Query()
125	
126		name, ok := singleValue(values, "name")
127		if !ok || strings.TrimSpace(name) == "" {
128			writeError(w, http.StatusBadRequest, "name is required and must be a single non-empty value")
129			return
130		}
131	
132		parseTime := func(param string) (time.Time, bool) {
133			raw, ok := singleValue(values, param)
134			if !ok || raw == "" {
135				writeError(w, http.StatusBadRequest, param+" is required and must be a single RFC3339Nano timestamp")
136				return time.Time{}, false
137			}
138			parsed, err := time.Parse(time.RFC3339Nano, raw)
139			if err != nil {
140				writeError(w, http.StatusBadRequest, param+" must be an RFC3339Nano timestamp")
141				return time.Time{}, false
142			}
143			return parsed, true
144		}
145		since, ok := parseTime("since")
146		if !ok {
147			return
148		}
149		until, ok := parseTime("until")
150		if !ok {
151			return
152		}
153		if !since.Before(until) {
154			writeError(w, http.StatusBadRequest, "since must be strictly before until")
155			return
156		}
157	
158		rawStep, ok := singleValue(values, "step")
159		if !ok || rawStep == "" {
160			writeError(w, http.StatusBadRequest, "step is required and must be a single integer number of seconds")
161			return
162		}
163		if !isDecimal(rawStep) {
164			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
165			return
166		}
167		stepSeconds, err := strconv.ParseInt(rawStep, 10, 64)
168		if err != nil || stepSeconds < minStepSeconds || stepSeconds > maxStepSeconds {
169			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
170			return
171		}
172	
173		// service is optional but, like the other parameters, may not repeat.
174		var service string
175		if rawServices, present := values["service"]; present {
