1	package httpapi
2	
3	import (
4		"net/http"
5		"strings"
6		"testing"
7		"time"
8	
9		"github.com/cocosolocoder/signalroom/internal/events"
10	)
11	
12	// bigMessageLen returns how many '<' characters an event needs for its saved
13	// encoding to exceed the save capacity. The save format escapes '<' as the
14	// six-byte sequence '<', while a literal '<' is a single request-body
15	// byte, so the request stays comfortably under the 16 MiB body limit even
16	// though it saves to over 64 MiB.
17	func bigMessageLen(t *testing.T, id string, at time.Time) (n int) {
18		t.Helper()
19		base := events.Event{ID: id, Service: "svc", Severity: "info", At: at}
20		lo, hi := 1, maxBodyBytes
21		for lo < hi {
22			mid := (lo + hi) / 2
23			base.Message = strings.Repeat("<", mid)
24			payload, err := events.MarshalBatch([]events.Event{base})
25			if err != nil {
26				t.Fatalf("marshal: %v", err)
27			}
28			if len(payload) > events.MaxBatchPayloadBytes {
29				hi = mid
30			} else {
31				lo = mid + 1
32			}
33		}
34		base.Message = strings.Repeat("<", lo)
35		payload, err := events.MarshalBatch([]events.Event{base})
36		if err != nil {
37			t.Fatalf("marshal: %v", err)
38		}
39		if len(payload) <= events.MaxBatchPayloadBytes {
40			t.Fatal("test setup failed to find an oversize length")
41		}
42		return lo
43	}
44	
45	func oversizeBody(id string, at string, n int) string {
46		return `{"events":[{"id":"` + id + `","service":"svc","severity":"info","message":"` +
47			strings.Repeat("<", n) + `","at":"` + at + `"}]}`
48	}
49	
50	// TestPostOversizeBatchIs400NotStorageFailure exercises the reported bug: a
51	// legal, sub-16-MiB request whose saved content escapes past 64 MiB must be a
52	// 400 telling the client to send less, never a 503 demanding a restart. The
53	// batch is rejected wholesale, the store stays usable, and the rejected ids
54	// remain free.
55	func TestPostOversizeBatchIs400NotStorageFailure(t *testing.T) {
56		server, store, _ := newTestServer(t)
57		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
58		n := bigMessageLen(t, "huge", at)
59		body := oversizeBody("huge", "2026-10-01T09:00:00Z", n)
60		if len(body) >= maxBodyBytes {
61			t.Fatalf("test setup: request body %d must be under the %d body limit", len(body), maxBodyBytes)
62		}
63	
64		status, out := post(t, server, body)
65		if status != http.StatusBadRequest {
66			t.Fatalf("oversize batch must be 400, got %d: %v", status, out)
67		}
68		msg, _ := out["error"].(string)
69		if msg == "" {
70			t.Fatal("error must be non-empty")
71		}
72		if !strings.Contains(msg, "save capacity") && !strings.Contains(strings.ToLower(msg), "reduce") {
73			t.Fatalf("error must explain the save capacity and ask for less content, got %q", msg)
74		}
75		if strings.Contains(strings.ToLower(msg), "restart") {
76			t.Fatalf("oversize error must not suggest a restart, got %q", msg)
77		}
78	
79		// Nothing durable was written, the store was not poisoned, and the
80		// rejected events are not visible.
81		if len(store.appended) != 0 {
82			t.Fatalf("oversize batch must not reach storage, appended %v", store.appended)
83		}
84		if store.Poisoned() {
85			t.Fatal("oversize batch must not poison storage")
86		}
87		if status, _ := get(t, server, ""); status != http.StatusOK {
88			t.Fatalf("store must stay available without a restart, got %d", status)
89		}
90	
91		// The rejected id can be reused immediately by a smaller batch.
92		small := `{"events":[{"id":"huge","service":"svc","severity":"info","message":"tiny","at":"2026-10-01T09:00:01Z"}]}`
93		if status, out := post(t, server, small); status != http.StatusOK {
94			t.Fatalf("rejected id must remain usable, got %d %v", status, out)
95		}
96		if status, found := get(t, server, ""); status != http.StatusOK || len(found.([]any)) != 1 {
97			t.Fatalf("only the small event should be present, got %d %v", status, found)
98		}
99	}
100	
101	// TestPostOversizeBatchRejectedWholesale ensures no partial save: a large
