1	package events
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"time"
9	
10		"github.com/cocosolocoder/signalroom/internal/strictjson"
11	)
12	
13	// eventDTO is the wire and on-disk representation of an event. Timestamps use
14	// RFC3339Nano, which time.Time produces and accepts natively. Labels is
15	// omitted entirely when an event has none, so frames written before labels
16	// existed decode unchanged.
17	type eventDTO struct {
18		ID       string            `json:"id"`
19		Service  string            `json:"service"`
20		Severity string            `json:"severity"`
21		Message  string            `json:"message"`
22		At       time.Time         `json:"at"`
23		Labels   map[string]string `json:"labels,omitempty"`
24	}
25	
26	// decodeLabels strictly decodes a JSON labels member; DecodeLabelsObject is
27	// the exported form used by request bodies that carry the same shape, such as
28	// the label filters in an alert preview request.
29	func decodeLabels(raw json.RawMessage) (map[string]string, error) {
30		return DecodeLabelsObject(raw)
31	}
32	
33	// DecodeLabelsObject strictly decodes a JSON labels object: null, absent, or
34	// an object whose values are all strings, and duplicate names are rejected
35	// instead of silently overwriting each other the way a plain map decode
36	// would. Name/value content rules are enforced later by NormalizeLabels or
37	// filter normalization.
38	func DecodeLabelsObject(raw json.RawMessage) (map[string]string, error) {
39		const what = "decode labels"
40		if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
41			return nil, nil
42		}
43		fields, err := strictjson.DecodeObject(raw, what, nil)
44		if err != nil {
45			return nil, labelsStructureError(err)
46		}
47		labels := make(map[string]string, len(fields))
48		for key, rawValue := range fields {
49			if bytes.Equal(rawValue, []byte("null")) {
50				return nil, fmt.Errorf("%s: value for %q must be a string", what, key)
51			}
52			var value string
53			if err := json.Unmarshal(rawValue, &value); err != nil {
54				return nil, fmt.Errorf("%s: value for %q must be a string", what, key)
55			}
56			labels[key] = value
57		}
58		if len(labels) == 0 {
59			return nil, nil
60		}
61		return labels, nil
62	}
63	
64	// labelsStructureError restores the labels wording on top of the shared
65	// structural rejection; the other kinds already render identically.
66	func labelsStructureError(err error) error {
67		var se *strictjson.Error
68		if !errors.As(err, &se) {
69			return err
70		}
71		switch se.Kind {
72		case strictjson.KindNotObject:
73			return errors.New("decode labels: must be an object of string values")
74		case strictjson.KindNameNotString:
75			return errors.New("decode labels: names must be strings")
76		case strictjson.KindDuplicateField:
77			return fmt.Errorf("decode labels: duplicate label name %q", se.Field)
78		default:
79			return err
80		}
81	}
82	
83	// allowedEventFields is the exact set of members each event object may
84	// carry; anything else is an unknown field.
85	var allowedEventFields = map[string]struct{}{
86		"id":       {},
87		"service":  {},
88		"severity": {},
89		"message":  {},
90		"at":       {},
91		"labels":   {},
92	}
93	
94	// MarshalBatch encodes normalized events as a JSON array with sorted keys.
95	func MarshalBatch(batch []Event) ([]byte, error) {
96		dtos := make([]eventDTO, len(batch))
97		for i, event := range batch {
98			dtos[i] = eventDTO{
99				ID:       event.ID,
100				Service:  event.Service,
101				Severity: event.Severity,
102				Message:  event.Message,
103				At:       event.At,
104				Labels:   event.Labels,
105			}
106		}
107		return json.Marshal(dtos)
108	}
109	
110	// DecodeBatch strictly decodes a JSON array of events. Unknown fields,
111	// syntax errors, malformed timestamps, malformed labels, trailing data, and
112	// duplicate member names within the outer array's event objects are
113	// rejected; callers remain responsible for emptiness and field validation.
114	// Names are compared after JSON decoding, so a literal name and its \uXXXX
115	// escape of the same text count as a repeat.
116	func DecodeBatch(data []byte) ([]Event, error) {
117		batch, err := strictjson.DecodeArray(data, "decode events array", decodeEventObject)
118		if err != nil {
119			return nil, eventsStructureError(err)
120		}
121		return batch, nil
122	}
123	
124	// eventsStructureError restores the event-batch wording for the shapes the
125	// shared scanner describes generically; syntax, unknown-field, duplicate,
126	// and trailing-data messages already match.
127	func eventsStructureError(err error) error {
128		var se *strictjson.Error
129		if !errors.As(err, &se) {
130			return err
131		}
132		switch se.Kind {
133		case strictjson.KindNotArray:
134			return errors.New("decode events array: must be an array of event objects")
135		case strictjson.KindNotObject:
136			return errors.New("decode events array: each entry must be an object")
137		case strictjson.KindNameNotString:
138			return errors.New("decode events array: event field names must be strings")
139		default:
140			return err
141		}
142	}
143	
144	// decodeEventObject reads one event object from dec, rejecting unknown
145	// members and repeated member names (after JSON unescaping). Values retain
146	// the same typed-decoding behavior as a struct decode: strings, RFC3339
147	// timestamps, and the strict labels shape.
148	func decodeEventObject(dec *json.Decoder) (Event, error) {
149		const what = "decode events array"
150		var event Event
151		err := strictjson.EachObjectField(dec, what, allowedEventFields, func(key string, raw json.RawMessage) error {
152			switch key {
153			case "id":
154				if err := json.Unmarshal(raw, &event.ID); err != nil {
155					return fmt.Errorf("%s: id has the wrong type", what)
156				}
157			case "service":
158				if err := json.Unmarshal(raw, &event.Service); err != nil {
159					return fmt.Errorf("%s: service has the wrong type", what)
160				}
161			case "severity":
162				if err := json.Unmarshal(raw, &event.Severity); err != nil {
163					return fmt.Errorf("%s: severity has the wrong type", what)
164				}
165			case "message":
166				if err := json.Unmarshal(raw, &event.Message); err != nil {
167					return fmt.Errorf("%s: message has the wrong type", what)
168				}
169			case "at":
170				if err := json.Unmarshal(raw, &event.At); err != nil {
