517		second := frame(`[{"id":"e1","service":"svc","severity":"info","message":"second","at":"2026-10-01T09:00:00Z"}]`)
518		tornPayload := []byte(`[{"id":"torn","service":"svc","severity":"info","message":"m","at":"2026-10-01T09:01:00Z"}]`)
519		torn := frame(string(tornPayload))[:8+4]
520		content := append(append(append([]byte(nil), first...), second...), torn...)
521		path := filepath.Join(dataDir, "events.log")
522		if err := os.WriteFile(path, content, 0o644); err != nil {
523			t.Fatal(err)
524		}
525	
526		logs := &safeBuffer{}
527		failing := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
528		failing.Stdout = logs
529		failing.Stderr = logs
530		if err := failing.Start(); err != nil {
531			t.Fatal(err)
532		}
533		done := make(chan error, 1)
534		go func() { done <- failing.Wait() }()
535		select {
536		case err := <-done:
537			if err == nil {
538				t.Fatal("conflicting log must prevent startup")
539			}
540			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
541				t.Fatalf("conflicting log must exit non-zero: %v", err)
542			}
543		case <-time.After(5 * time.Second):
544			failing.Process.Kill()
545			t.Fatal("server stayed up despite conflicting records")
546		}
547	
548		out := logs.String()
549		if !strings.Contains(out, `"e1"`) || !strings.Contains(out, "different content") {
550			t.Fatalf("error must name the conflicting id and the content clash:\n%s", out)
551		}
552		if strings.Contains(out, "listening on") {
553			t.Fatalf("failed startup must not announce readiness:\n%s", out)
554		}
555		after, err := os.ReadFile(path)
556		if err != nil {
557			t.Fatal(err)
558		}
559		if !bytes.Equal(after, content) {
560			t.Fatal("failed startup must not modify events.log, torn tail included")
561		}
562	}
