	dataDir := t.TempDir()
	payload := []byte(`[{"id":"e1","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"},{"id":"e2","service":"s","severity":"info","message":"m","at":"2026-10-01T09:01:00Z"}]`)
	frame := make([]byte, 8+len(payload))
