func TestCreateKeepsInteriorCase(t *testing.T) {
	reg, _, _ := newTestRegistry(&fakeEvents{})
	in := validCreation()
	in.Title = "Payments API Down"
	if _, err := reg.Create(in); err != nil {
		t.Fatal(err)
